import { cookies } from 'next/headers'
import { toggleNotificationPreference } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const notificationsOn = cookieStore.get('notifications')?.value === 'on'

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {notificationsOn ? 'on' : 'off'}.</p>
      <form action={toggleNotificationPreference}>
        <button type="submit">
          Turn notifications {notificationsOn ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

